exercises.solution:
console.log(NaN === NaN); // false - NaN nie jest rowny SAMEMU SOBIE

function jestNaN(wartosc) {
  return Number.isNaN(wartosc);
}

jestNaN(0 / "tekst"); // true
jestNaN(42); // false

function porownajScisle(a, b) {
  return a === b;
}

porownajScisle(5, 5);     // true
porownajScisle(5, "5");   // false
porownajScisle("a", "a"); // true

function jestPusteLubBrak(wartosc) {
  return wartosc == null;
}

jestPusteLubBrak(null);      // true
jestPusteLubBrak(undefined); // true
jestPusteLubBrak(0);         // false
jestPusteLubBrak("");        // false

function jestPusteLubBrakScisle(wartosc) {
  return wartosc === null || wartosc === undefined;
}

jestPusteLubBrakScisle(null);      // true
jestPusteLubBrakScisle(undefined); // true
jestPusteLubBrakScisle(0);         // false

const idZAPI = "42";
const szukaneId = 42;

if (Number(idZAPI) === szukaneId) {
  console.log("Znaleziono");
}
// "Znaleziono" - konwersja jawna, kontrolowana, zamiast ukrytej w ==

// === jest ZAWSZE przewidywalne - porownuje wartosc I typ, bez ukrytej
// konwersji. == wykonuje NIEJAWNA konwersje typow PRZED porownaniem, co
// prowadzi do zaskakujacych, nieintuicyjnych wynikow, np.:
// 1. 0 == false -> true (false konwertowane do 0, mimo ze to zupelnie
//    rozne koncepcyjnie wartosci - liczba i wartosc logiczna)
// 2. [] == false -> true (pusta tablica konwertowana najpierw do stringa
//    "", potem do liczby 0, a nastepnie porownywana z 0) - bardzo trudne
//    do przewidzenia bez znajomosci dokladnych regul konwersji
// Dlatego === jest bezpiecznym domyslnym wyborem - eliminuje cala klase
// bledow wynikajacych z nieoczekiwanej, ukrytej konwersji typow.

function czyRowne(a, b) {
  return a === b;
}

console.log(czyRowne(1, 1));            // -> true
console.log(czyRowne(1, "1"));          // -> false
console.log(czyRowne(NaN, NaN));        // -> false
console.log(czyRowne(null, undefined)); // -> false

function porownajZKonwersja(napis, liczba) {
  return Number(napis) === liczba;
}

console.log(porownajZKonwersja("42", 42));  // -> true
console.log(porownajZKonwersja("abc", 42)); // -> false (Number("abc") to NaN)

const pierwszy = { a: 1 };
const inny = { a: 1 };
const drugi = pierwszy;

console.log(pierwszy === inny);  // -> false (rozne obiekty w pamieci)
console.log(pierwszy === drugi); // -> true (ta sama referencja)

function rownaTablice(a, b) {
  return a.length === b.length && a.every((element, i) => element === b[i]);
}

console.log(rownaTablice([1, 2, 3], [1, 2, 3])); // -> true
console.log(rownaTablice([1, 2, 3], [1, 2, 4])); // -> false
console.log([1, 2, 3] === [1, 2, 3]);            // -> false (samo === porownuje referencje)

function pomijajPuste(tablica) {
  return tablica.filter(element => element != null);
}

console.log(pomijajPuste([1, null, 0, undefined, "", "x"]));
// -> [1, 0, "", "x"]

const dane = [0, 1, "", "a", null, undefined, false, NaN];
console.log(dane.filter(Boolean)); // -> [1, "a"]
// znikaja: 0, "", null, undefined, false i NaN

function znajdzPoId(uzytkownicy, id) {
  return uzytkownicy.find(u => u.id === Number(id));
}

const uzytkownicy = [{ id: 1, imie: "Ala" }, { id: 2, imie: "Jan" }];
console.log(znajdzPoId(uzytkownicy, "2")); // -> { id: 2, imie: "Jan" }
console.log(znajdzPoId(uzytkownicy, "9")); // -> undefined

function czyLiczbaCalkowita(x) {
  return typeof x === "number" && Number.isInteger(x);
}

console.log(czyLiczbaCalkowita(5));   // -> true
console.log(czyLiczbaCalkowita("5")); // -> false
console.log(czyLiczbaCalkowita(5.5)); // -> false

const tablica = [NaN];
console.log(tablica.includes(NaN)); // -> true
console.log(tablica.indexOf(NaN));  // -> -1 (indexOf uzywa ===, a NaN !== NaN)

function sprawdzWiek(tekst) {
  const wiek = Number(tekst);
  if (Number.isNaN(wiek)) return "niepoprawny wiek";
  if (wiek === 18) return "dokladnie 18";
  return "inny wiek";
}

console.log(sprawdzWiek("abc")); // -> "niepoprawny wiek"
console.log(sprawdzWiek("18"));  // -> "dokladnie 18"
console.log(sprawdzWiek("30"));  // -> "inny wiek"

switch ("1") {
  case 1:
    console.log("liczba");
    break;
  default:
    console.log("default"); // -> "default"
}
// switch uzywa === - napis "1" nie jest scisle rowny liczbie 1.

function jestPustyTekst(tekst) {
  return tekst === "";
}

console.log(jestPustyTekst(""));   // -> true
console.log(jestPustyTekst(" "));  // -> false
console.log(jestPustyTekst(0));    // -> false
console.log(jestPustyTekst(null)); // -> false
// Dla porownania: 0 == "" jest true, a null == "" jest false

const suma = 0.1 + 0.2;
console.log(suma === 0.3);                           // -> false
console.log(Math.abs(suma - 0.3) < 0.000001);  // -> true

function rownaBezWielkosci(a, b) {
  return a.toLowerCase() === b.toLowerCase();
}

console.log(rownaBezWielkosci("Ala", "ALA")); // -> true
console.log(rownaBezWielkosci("Ala", "Ola")); // -> false

const a = new Date(0);
const b = new Date(0);
console.log(a === b);                       // -> false
console.log(a.getTime() === b.getTime());   // -> true

function typRownosci(a, b) {
  if (a === b) return "scisle";
  if (a == b) return "luzno";
  return "rozne";
}

console.log(typRownosci(1, 1));   // -> "scisle"
console.log(typRownosci(1, "1")); // -> "luzno"
console.log(typRownosci(1, 2));   // -> "rozne"

